subscriptions.schema:
message gram.intentpolicy.v1.Assessment {
	required group __pubsub {
		required binary message_id (STRING);
		required int64 received_micros (INT(64,true));
		required binary topic (STRING);
	}
	optional group actor {
		required boolean __present;
		optional binary user_email (STRING);
		optional binary user_id (STRING);
	}
	optional binary analysis_id (STRING);
	optional binary analysis_requested_at (STRING);
	required group contracts (LIST) {
		repeated group list {
			required group element {
				required boolean __present;
				optional binary contract_id (STRING);
				optional binary error (STRING);
				required group inputs (MAP) {
					repeated group key_value {
						required binary key (STRING);
						required binary value (STRING);
					}
				}
				optional binary result (STRING);
			}
		}
	}
	required group decided_by (LIST) {
		repeated group list {
			required binary element (STRING);
		}
	}
	optional binary decision (STRING);
	optional binary evaluated_at (STRING);
	optional group evaluator {
		required boolean __present;
		optional binary kind (STRING);
		optional binary model (STRING);
		optional binary prompt_version (STRING);
		optional binary provider (STRING);
	}
	optional binary evaluator_error (STRING);
	optional group guardrail {
		required boolean __present;
		optional binary id (STRING);
		optional binary version (STRING);
	}
	optional binary id (STRING);
	required group labels (LIST) {
		repeated group list {
			required group element {
				required boolean __present;
				optional boolean bool_value;
				optional binary choice_value (STRING);
				required group distribution (MAP) {
					repeated group key_value {
						required binary key (STRING);
						required double value;
					}
				}
				optional binary key (STRING);
				optional int32 kind (INT(32,true));
				required group members (LIST) {
					repeated group list {
						required binary element (STRING);
					}
				}
				optional double probability;
				optional int32 rank (INT(32,true));
				optional binary rationale (STRING);
			}
		}
	}
	optional binary organization_id (STRING);
	optional binary project_id (STRING);
	optional group tool_call {
		required boolean __present;
		optional int64 arguments_bytes (INT(64,true));
		optional binary arguments_sha256 (STRING);
		optional binary chat_id (STRING);
		optional int32 generation (INT(32,true));
		optional binary mcp_function (STRING);
		optional binary mcp_server (STRING);
		optional binary message_id (STRING);
		optional binary occurred_at (STRING);
		optional int64 sequence (INT(64,true));
		optional binary tool_call_id (STRING);
		optional binary tool_name (STRING);
	}
	optional binary trigger_kind (STRING);
	optional group usage {
		required boolean __present;
		optional double cost_usd;
		optional int64 input_tokens (INT(64,true));
		optional int64 latency_ms (INT(64,true));
		optional int64 output_tokens (INT(64,true));
	}
}

message gram.sigint.v1.Reading {
	optional int32 __oneof_result (INT(32,true));
	required group __pubsub {
		required binary message_id (STRING);
		required int64 received_micros (INT(64,true));
		required binary topic (STRING);
	}
	optional group account {
		required boolean __present;
		optional binary account_type (STRING);
		optional binary billing_mode (STRING);
		optional binary user_account_id (STRING);
	}
	optional group actor {
		required boolean __present;
		optional binary external_user_id (STRING);
		optional binary user_email (STRING);
		optional binary user_id (STRING);
	}
	optional binary assistant_id (STRING);
	required group attributes (MAP) {
		repeated group key_value {
			required binary key (STRING);
			required binary value (STRING);
		}
	}
	optional binary billing_user_id (STRING);
	optional group choice {
		required boolean __present;
		optional double confidence;
		required group distribution (LIST) {
			repeated group list {
				required group element {
					required boolean __present;
					optional double probability;
					optional binary signal_id (STRING);
					optional binary signal_slug (STRING);
				}
			}
		}
		optional binary selected_signal_id (STRING);
		optional binary selected_signal_slug (STRING);
	}
	optional binary compiler_version (STRING);
	optional binary configured_model (STRING);
	optional binary definition_hash (STRING);
	optional binary evaluated_at (STRING);
	optional binary evaluation_attempt_id (STRING);
	optional binary evaluation_requested_at (STRING);
	optional group event {
		optional int32 __oneof_context (INT(32,true));
		required boolean __present;
		optional group conversation_message {
			required boolean __present;
			optional binary capture_kind (STRING);
			optional binary conversation_id (STRING);
			optional int32 generation (INT(32,true));
			optional binary original_message_id (STRING);
			optional int32 role (INT(32,true));
			optional int64 sequence (INT(64,true));
		}
		optional binary id (STRING);
		optional binary kind (STRING);
		optional binary occurred_at (STRING);
		optional group tool_call {
			required boolean __present;
			optional binary mcp_server_id (STRING);
			optional binary tool_call_id (STRING);
			optional binary tool_name (STRING);
		}
	}
	optional binary id (STRING);
	optional group input {
		required boolean __present;
		optional int32 message_count (INT(32,true));
		optional int32 requested_message_count (INT(32,true));
		optional binary strategy (STRING);
		optional boolean truncated;
	}
	required group models (LIST) {
		repeated group list {
			required binary element (STRING);
		}
	}
	optional group multi_label {
		required boolean __present;
		required group signals (LIST) {
			repeated group list {
				required group element {
					required boolean __present;
					optional double probability;
					optional binary signal_id (STRING);
					optional binary signal_slug (STRING);
				}
			}
		}
	}
	optional binary organization_id (STRING);
	optional binary project_id (STRING);
	optional binary provider (STRING);
	optional boolean replayed;
	optional binary run_id (STRING);
	optional group score {
		required boolean __present;
		optional double confidence;
		required group distribution (LIST) {
			repeated group list {
				required group element {
					required boolean __present;
					optional double probability;
					optional binary signal_id (STRING);
					optional binary signal_slug (STRING);
				}
			}
		}
		optional double expected_index;
	}
	optional binary sensor_id (STRING);
	optional binary sensor_slug (STRING);
	optional binary source (STRING);
	optional binary trigger_kind (STRING);
}
